    "requirementsEn": "General entry requirements for all masters programmes — China: Top 100 of 2026 Shanghai Ranking, or World-class universities, or First-class disciplines (MoE, People's Republic of China): 75 per cent or above (Weighted Average Mark); Other universities: 80 – 85 per cent or above (Weighted Average Mark), depending on your undergraduate institution. Note: Shanghai Ranking of The Best Chinese Universities is subject to annual update. Programme-specific entry requirements (official original text): Undergraduate background Bachelor Degree in mathematics-related discipline, such as mathematics, applied mathematics, statistics, data science, finance, or insurance. English language requirement IELTS 6.5 (minimum 5.5 in all sections). TOEFL iBT or PTE Academic are also accepted. Please refer to the equivalence table below. Additional requirements No work experience required. Applicants who do not meet these course entry academic requirements may still be considered in exceptional cases. The School will consider each application that demonstrates additional strengths and alternative evidence. This might, for example, be demonstrated by: Related work experience; A strong portfolio and/or professional reference OR a combination of factors 官网注明 TOEFL iBT 与 PTE Academic 亦被接受，具体分数对照见官网入学要求页的 equivalence table。",
