    "desc": "By the time you graduate from the MSc Entrepreneurship and Innovation programme, you will have gained: advanced awareness of current theories, trends and techniques in the theory, practice and research of Entrepreneurship and Innovation; the ability to compete for opportunities and transform them into viable concepts and business ideas; the skills to plan, manage and resource entrepreneurial business activities; the capability to evaluate, research, write and present business plans/feasibility studies utilising key relevant frameworks and concepts; an understanding of the importance of ethical and social responsi",
    "descEn": "By the time you graduate from the MSc Entrepreneurship and Innovation programme, you will have gained: advanced awareness of current theories, trends and techniques in the theory, practice and research of Entrepreneurship and Innovation; the ability to compete for opportunities and transform them into viable concepts and business ideas; the skills to plan, manage and resource entrepreneurial business activities; the capability to evaluate, research, write and present business plans/feasibility studies utilising key relevant frameworks and concepts; an understanding of the importance of ethical and social responsi",
    "descCn": "毕业时你将获得：对创业与创新在理论、实践与研究层面的当代理论、趋势与方法的进阶认知；竞争机会并将其转化为可行概念与商业创意的能力；规划、管理并为创业型商业活动配置资源的技能。",
