    "desc": "By the time you graduate from the MSc Finance programme, you will have: a strong academic foundation, including a solid understanding of theoretical frameworks and modes of enquiry that underpin postgraduate study in finance; an understanding of key issues and frontier developments in finance, financial management, and digital finance; the ability to apply quantitative techniques to analyse and interpret complex financial data and academic literature; the capability to independently design, plan, and complete a substantial research project in the field of finance; and a deep understanding of the transformative im",
    "descEn": "By the time you graduate from the MSc Finance programme, you will have: a strong academic foundation, including a solid understanding of theoretical frameworks and modes of enquiry that underpin postgraduate study in finance; an understanding of key issues and frontier developments in finance, financial management, and digital finance; the ability to apply quantitative techniques to analyse and interpret complex financial data and academic literature; the capability to independently design, plan, and complete a substantial research project in the field of finance; and a deep understanding of the transformative im",
    "descCn": "毕业时你将具备：扎实的学术基础，包括对支撑金融领域研究生学习的理论框架与研究范式的深入理解；对金融、财务管理与数字金融领域关键议题及前沿发展的认识；运用量化技术分析与解读复杂金融数据及学术文献的能力；独立设计、规划并完成金融领域实质性研究项目的能力；以及对机器学习、数字金融与区块链等技术如何重塑金融业的深刻理解。",
