    "requirementsEn": "General entry requirements for all masters programmes — China: Top 100 of 2026 Shanghai Ranking, or World-class universities, or First-class disciplines (MoE, People's Republic of China): 75 per cent or above (Weighted Average Mark); Other universities: 80 – 85 per cent or above (Weighted Average Mark), depending on your undergraduate institution. Note: Shanghai Ranking of The Best Chinese Universities is subject to annual update. Programme-specific entry requirements (official original text): Undergraduate background Bachelor Degree or equivalent academic qualification / experience in a relevant area such as computer science, information systems, with some programming and program design experience. Additional requirements Applicants who do not meet the standard entry requirements but have substantial relevant work experience will be considered for enrolment in the programme on a case-by-case basis. English language requirement IELTS 6.0 (minimum 5.5 in all sections). TOEFL iBT or PTE Academic are also accepted. Please refer to the equivalence table below. 官网注明 TOEFL iBT 与 PTE Academic 亦被接受，具体分数对照见官网入学要求页的 equivalence table。",
