    "desc": "By the time you graduate from the MSc Business Analytics programme, you will have: a deep understanding of cutting-edge, practice-oriented approaches to big data processing and data management, alongside advanced business concepts; the ability to analyse and model complex networks and organisations; a strong set of data-processing and problem-solving skills; proficiency in a range of statistical software packages suitable for analysing large data sets; and the opportunity to benefit from IBSS’s research centres and extensive industry links with companies in Suzhou and Shanghai, which will support your research an",
    "descEn": "By the time you graduate from the MSc Business Analytics programme, you will have: a deep understanding of cutting-edge, practice-oriented approaches to big data processing and data management, alongside advanced business concepts; the ability to analyse and model complex networks and organisations; a strong set of data-processing and problem-solving skills; proficiency in a range of statistical software packages suitable for analysing large data sets; and the opportunity to benefit from IBSS’s research centres and extensive industry links with companies in Suzhou and Shanghai, which will support your research an",
    "descCn": "毕业时你将具备：对前沿且面向实践的大数据处理与数据管理方法，以及进阶商业概念的深入理解；分析与建模复杂网络及组织的能力；一套扎实的数据处理技能。",
