    "category": "会计",
    "desc": "By the time you graduate from the MSc Professional Accounting programme, you will: understand how emerging technologies are reshaping the profession, through modules on artificial intelligence and accounting and more; havestrong professional accounting capabilities, including financial decision-making, evaluation, and analysis of financial data, as well as the techniques needed to tackle complex financial and tax-related issues in practice; have a solid grounding in core areas such as financial reporting, audit and assurance, taxation, and corporate finance (where covered), ready for real workplace application; h",
    "descEn": "By the time you graduate from the MSc Professional Accounting programme, you will: understand how emerging technologies are reshaping the profession, through modules on artificial intelligence and accounting and more; havestrong professional accounting capabilities, including financial decision-making, evaluation, and analysis of financial data, as well as the techniques needed to tackle complex financial and tax-related issues in practice; have a solid grounding in core areas such as financial reporting, audit and assurance, taxation, and corporate finance (where covered), ready for real workplace application; h",
