    "applyWindow": "官网中文入学申请页原文：常规批——2027年秋季入学常规批次于2026年8月24日开启申请，2027年5月31日截止申请。申请人应在截止日期前递交申请材料，入围者将适时获邀参加面试。本项目采用滚动制招生审核，招满即止，建议申请人尽早提交申请。*具体面试轮次请见项目官网及官方微信公众号通知。提前批（仅针对大三在读学生）：1.夏令营-迷你营（每年3-5月举行）；2.夏令营-体验营（每年7月举行）。中文首页「申请截止日期」区块原文：5月31 常规批申请 2027年入学（已开启）；4月30 夏令营-迷你营 2027年入学（已结束）；6月15 夏令营-体验营 2026年入学（已结束）。截至 2026-09-21 常规批正在开放。⚠ 英文页 /en/admission 的 Application Deadline 表仍为「Starting Date 1/9/2025、Closing Date 31/5/2026」，落后一年，不可作为 27 Fall 依据，本库以中文页为准。申请网址 https://pgapply.cuhk.edu.cn/ ，申请费人民币 600 元（不退款）。香港中文大学（深圳）获得国家教育部批准可自主招生，申请者不需要参加全国研究生统一考试；材料审核初筛后，符合项目要求的申请者会进行笔试/面试考核。",
