    "sourceNote": "2026-09-20 由该项目独立官网子站（msecon.cuhk.edu.cn）浏览器实抓核实：学费、学制、申请要求、申请批次、奖学金均取自官网中文原文，未改写、未推算。所属学院取自港中深经管学院官网导航「课程项目 · 全日制理学硕士」分组。本项目为全日制，兼读制按口径不收录。官网未列开办年份，故 foundedYear 留空不推算。 2026-09-21 复核：英文简介原文与英文入学要求原文已按该子站 /en 页面逐字回填（此前仅有中文站原文）；学费与申请轮次以本轮中英文两版原文交叉印证。"
