    "tuitionNote": "官网原文（中文入学申请页）：学费 31.8万人民币（2026年）。英文页原文：RMB 318,000 (US $ 43.8k approx.) for 2026 Intake. 注意官网中英两版标注的均是 2026 年入学而非 2027 年入学；官网首页与申请日期表已明确开放「2027年秋季入学」三轮申请，但学费栏未同步更新。按「不编造、不推算」原则，本库不将 2026 年数额当作 27 Fall 费用，tuitionRmb / tuitionCny 留空，须待官网公布 2027 年入学学费后重核。官网中文页「在线申请」栏亦仍写「2026年入学请登录 研究生网申系统…并交纳申请费600元（不予退款）」。奖学金（中文页原文）：项目组将根据面试表现及综合条件择优颁发奖学金，最高可豁免100%学费——全额奖学金 全额学费；博文奖学金 23.8万；半额奖学金 半额学费；励耘一等奖学金 10万；励耘二等奖学金 7万；另设海外实习奖学金、项目贡献奖学金、学习成就奖学金（英文页：Full Scholarship Full-Tuition; Bowen Scholarship RMB238,000; Half Scholarship Half-Tuition; Liyun Tier-1 Scholarship RMB100,000; Liyun Tier-2 Scholarship RMB70,000; 及 Internship Abroad / Outstanding Contribution / Merit Scholarship）。申请费人民币 600 元，不予退款。",
