    "applyWindow": "官网中文首页「申请截止日期」区块原文：8月26 —— 2027年秋季入学研究生申请，申请期间：2026年8月26日 - 2026年11月30日，第一轮；6月20 —— 2027年秋季入学夏令营申请，2026年4月10日（北京）、2026年5月10日（上海）、2026年6月20日（深圳），已结束。入学申请页「申请日期」表原文：第一轮 2026年8月26日—2026年11月30日；第二轮 2026年12月1日—2027年2月28日；第三轮 2027年3月1日—2027年4月30日。（英文页 Application Schedule 同表原文：Round 1 Aug. 26th, 2026- Nov. 30th, 2026; Round 2 Dec. 1st, 2026 - Feb. 28th, 2027; Round 3 Mar. 1st, 2027 - Apr. 30th, 2027.）官网明确该三轮对应「2027年秋季入学」；截至 2026-09-21 第一轮正在开放。申请费人民币 600 元（不予退款），须通过研究生网申系统 https://pgapply.cuhk.edu.cn/ 在线提交；部分通过材料初审的申请者需受邀参加现场面试；数据科学项目要求至少 1 封学术导师的推荐信。⚠ 官网「在线申请」栏仍写「2026年入学请登录 研究生网申系统」、学费栏仍写「31.8万人民币（2026年）」，均未更新到 2027 年，故本条学费数值留空。",
