    "tuitionNote": "官网 2027 招生新闻页（/en/node/4071「2027 Fall Admission — Regular Round Now Open」，发布时间 2026-08-20）原文：学费（2027 入学）Tuition (2027 intake)：人民币 29.7 万元 RMB 297,000；学制 Duration：全日制 2 年 Full-time, 2 years；总学分 Total Credits：36 学分；入学时间 Intake：2027 年秋季 Fall 2027。同页附注原文：*The tuition fee is for the full 36 credits of the major. The total tuition fee is based on the current year of enrollment.（学费为修满 36 专业学分的费用，总额以当年入学为准；经教育部等相关部门批准实行学分制收费的学校，加修其他专业课程或重修课程按所修课程规定的学分收费标准另收。）⚠ 官网 /en/admission 页与费用 FAQ 页仍写「The tuition fee for the entire programme (2025 entry) is RMB 267,000」「The total tuition fee for 2025 entry is RMB 267,000, which is paid in installments.」——该两页为 2025 年入学的过时数据，本库以 2027 招生新闻页为准。申请费：人民币 600 元，不设退款（官网另有「申请费用为 100 元，不设退款」的旧批次表述，现行 /en/admission 页与 2027 招生页均为 600 元）。缴费方式（官网 2025 年入学原文，供参考）：总学费分期缴纳，第一笔为总学费的 40%，须在 14 天内缴纳；其余按录取通知书指引缴纳。奖学金：入学奖学金择优发放，最高可豁免 100% 学费；另设学业奖学金（Scholarships for Academic Excellence）。学费不含书本费（FAQ 原文：No, students will need to pay for their own books and other supplies.）。",
    "durationYears": 2,
    "durationText": "全日制 24 个月标准学制（修满 7 门专业必修课及 5 门专业选修课）",
    "foundedYear": null,
    "open27": true,
    "applyWindow": "官网 2027 招生新闻页（/en/node/4071「2027 Fall Admission — Regular Round Now Open」，发布时间 2026-08-20）原文：2027 年常规批入学申请已正式开启，自 2026 年 8 月 20 日起接受申请。第一轮：2026 年 9 月 15 日；第二轮：2026 年 10 月 13 日；第三轮：2026 年 11 月 10 日；第四轮：2026 年 12 月 15 日；后续申请轮次安排待定。温馨提示：项目采取滚动制招生，招满即止。建议申请者尽早准备并提交申请。（英文原文：Applications for the 2027 regular intake are now open, starting from 20 August 2026. Round 1: 15 September 2026; Round 2: 13 October 2026; Round 3: 10 November 2026; Round 4: 15 December 2026; Further rounds, if any, will be announced later. Note: Admissions are conducted on a rolling basis. Seats are filled on a first-qualified, first-served basis.）该新闻页标注的活动时间区间为 2026-08-20 至 2027-05-31。截至 2026-09-21：第一轮（2026-09-15）已截止，第二轮（2026-10-13）为下一轮，整体申请开放中。申请流程：在线申请 → 材料审核 → 线上面试 → 材料复核 → 录取入学。申请网址 https://pgapply.cuhk.edu.cn/ ，申请费人民币 600 元不设退款。香港中文大学（深圳）获得国家教育部批准可自主招生，申请者不需要参加全国研究生统一考试。",
    "jointPartner": null,
    "location": "深圳（香港中文大学（深圳）校区）",
