    "sourceNote": "2026-09-20 由该项目独立官网子站（mscmkt.cuhk.edu.cn）浏览器实抓核实：学费、学制、申请要求、申请批次、奖学金均取自官网中文原文，未改写、未推算。所属学院取自港中深经管学院官网导航「课程项目 · 全日制理学硕士」分组。本项目为全日制，兼读制按口径不收录。官网未列开办年份，故 foundedYear 留空不推算。 2026-09-21 复核实并更正：官网发布 2027 招生新闻页 /en/node/4071「2027 Fall Admission — Regular Round Now Open」（2026-08-20），首次明确公布 2027 年入学学费人民币 297,000 元、全日制 2 年、36 学分、2027 年秋季入学，并给出四轮申请截止日期。据此 open27 由 pending 更正为 true，tuitionRmb / tuitionCny 由空值补为 297000，feeSource 由 official-other-intake 更正为 official-page。此前本库依 /en/admission 页「(2025 entry) RMB 267,000」判断学费未公布，属该页更新滞后所致。申请费统一为人民币 600 元（此前记录的「100 元」为旧批次文案，已在学费说明中披露）。英文简介与英文入学要求原文已按 /en/about-sfi、/en/admission、/en/node/4071 逐字回填。",
