    "category": "可持续",
    "desc": "In the global effort to address climate change, achieving carbon neutrality has become a shared goal among nations. Green finance is playing a pivotal role in enabling this transition. There is an urgent need for professionals with cross-disciplinary expertise, well-versed in both low-carbon technologies and financial instruments, given the global proliferation of carbon pricing mechanisms and the increasing scale of ESG investments. The Master of Science in Carbon Neutrality and Green Finance (MSc CNGF) program at HKUST(GZ) aims to cultivate future leaders in this field. Leveraging the Guangdong-Hong Kong-Macao Greater Bay Area's strengths in green finance innovation, the program brings together expertise from environmental science, energy engineering, finance, and public policy to create a comprehensive educational framework.",
    "descEn": "In the global effort to address climate change, achieving carbon neutrality has become a shared goal among nations. Green finance is playing a pivotal role in enabling this transition. There is an urgent need for professionals with cross-disciplinary expertise, well-versed in both low-carbon technologies and financial instruments, given the global proliferation of carbon pricing mechanisms and the increasing scale of ESG investments. The Master of Science in Carbon Neutrality and Green Finance (MSc CNGF) program at HKUST(GZ) aims to cultivate future leaders in this field. Leveraging the Guangdong-Hong Kong-Macao Greater Bay Area's strengths in green finance innovation, the program brings together expertise from environmental science, energy engineering, finance, and public policy to create a comprehensive educational framework.",
    "descCn": "在全球应对气候变化的努力中，实现碳中和已成为各国的共同目标，而绿色金融正在推动这一转型中发挥关键作用。随着全球碳定价机制不断扩展、ESG 投资规模持续上升，市场迫切需要既精通低碳技术、又熟悉金融工具的跨学科专业人才。港科大（广州）碳中和与绿色金融理学硕士项目旨在培养该领域的未来领导者。项目依托粤港澳大湾区在绿色金融创新方面的优势，整合环境科学、能源工程、金融与公共政策四个领域的师资，构建完整的教学框架。",
    "requirements": "1. General Admission Requirements of the University: Applicants seeking admission to a master's degree program should have obtained a bachelor's degree from a recognized institution, or an approved equivalent qualification. 2. English Language Admission Requirements: TOEFL-iBT 80 (for tests taken prior to 21 January 2026) / 4.5 (for tests taken from 21 January 2026 onwards); TOEFL-pBT 550; TOEFL-Revised paper-delivered test 60 (total scores for Reading, Listening and Writing sections); IELTS (Academic Module) overall score 6.5 and all sub-scores 5.5. Curriculum credits: Core Courses 10, Elective Courses 15, Project 3, Internship 6. Subject to the approval of the Program Director, students who have taken equivalent courses at other recognized universities may be granted credit transfer on a case-by-case basis, up to a maximum of 12 credits.",
    "requirementsEn": "1. General Admission Requirements of the University: Applicants seeking admission to a master's degree program should have obtained a bachelor's degree from a recognized institution, or an approved equivalent qualification. 2. English Language Admission Requirements: TOEFL-iBT 80 (for tests taken prior to 21 January 2026) / 4.5 (for tests taken from 21 January 2026 onwards); TOEFL-pBT 550; TOEFL-Revised paper-delivered test 60 (total scores for Reading, Listening and Writing sections); IELTS (Academic Module) overall score 6.5 and all sub-scores 5.5. Curriculum credits: Core Courses 10, Elective Courses 15, Project 3, Internship 6. Subject to the approval of the Program Director, students who have taken equivalent courses at other recognized universities may be granted credit transfer on a case-by-case basis, up to a maximum of 12 credits.",
    "requirementsCn": "一、全校通用入学要求：申请硕士学位者须已从认可院校取得学士学位，或具备经批准的同等资历。二、英语要求：TOEFL-iBT 80（2026 年 1 月 21 日前考试）/ 4.5（2026 年 1 月 21 日起考试）；TOEFL-pBT 550；TOEFL 纸笔改版考试 60（阅读、听力、写作三项总分）；IELTS 学术类总分 6.5 且各单项不低于 5.5。课程学分：核心课 10、选修课 15、项目 3、实习 6；经课程主任批准，在其他认可院校修读过同等课程者可按个案获学分转移，最多 12 学分。",
