    "sourceNote": "2026-09-20 浏览器实抓核实。判定依据为 HKUST 霍英东研究生院（广州）官方项目目录 pcc.hkust-gz.edu.cn/postgraduate/program-catalog（该目录为 iframe 内嵌的前端应用，静态抓取正文为空，必须用浏览器）。全院 2026/27 目录共 22 个项目，其中授课制 MSc 仅 4 个：Data-Centric AI Technology、Smart Manufacturing、Carbon Neutrality and Green Finance、Technology and Policy；另有 Innovation and Entrepreneurship MBA（按口径排除）与 Computational Arts MFA（艺术，非商科）。本库收录其中 2 个符合商科及商科交叉口径者：绿色金融（金融交叉）与数据为中心的人工智能技术（AI/数据科学交叉）。Smart Manufacturing 属工程、Technology and Policy 属科技政策，均不在「数据分析/数据科学/人工智能/统计学/经济学及与之交叉的商科项目」口径内，故不收。学费与学制取自项目自身官网页（研究生院目录该栏写 Please refer to the Program's website）。本项目 Mode of Study 官网明确为 Full-time（仅全日制），符合「只收全日制」口径。 课程主任 Prof Coco Dijia DU（碳中和与气候变化学域研究副教授）；项目咨询邮箱 msc-cngf@hkust-gz.edu.cn。 官网未列开办年份，foundedYear 留空不推算。项目目录页：https://pcc.hkust-gz.edu.cn/postgraduate/program-catalog/carbon-neutrality-and-green-finance-2"
