    "descEn": "Master of Science in Data-Centric Artificial Intelligence Technology (MSc DCAI). Full-time and Part-time. Duration: Full-time 2 yrs, Part-time 3 yrs. Total no. of credits: 39 credits/program. Medium of Instruction: English. Face-to-face mode of delivery (some courses may be delivered in mixed mode to allow in-need students to attend the courses via real-time online mode). Degree awarded: Master of Science (MSc), The Hong Kong University of Science and Technology. Offered by the Data Science and Analytics Thrust Area, Information Hub, HKUST(GZ).",
    "descCn": "数据为中心的人工智能技术理学硕士（MSc DCAI）由港科大（广州）信息枢纽数据科学与分析学域开设。设全日制与兼读制，全日制 2 年、兼读制 3 年；全程 39 学分；授课语言为英语；以面授为主（部分课程可采用混合模式，便于有需要的学生以实时在线方式修读）。特别注意：所授学位为 Master of Science (MSc)，颁授机构是 The Hong Kong University of Science and Technology（香港科技大学），而非「港科大（广州）」名义，这一点与港中深等项目不同，申请时须留意。",
    "requirements": "1. General Admission Requirements of the University: Please refer to Admission Requirements. 2. English Language Admission Requirements: Please refer to Admission Requirements. 3. Additional Information — Candidates with the following qualifications are preferred: a good honors degree in Data Science or AI; or a good honors degree in a related discipline with 2 years' experience in IT industry; or a good bachelor's degree in Data Science or AI with 2 years' experience in IT industry. Candidates with Data Analytic background can also be considered.",
