    "requirementsCn": "一、全校通用入学要求：见全校 Admission Requirements 页（申请硕士学位须已从认可院校取得学士学位或经批准的同等资历）。二、英语要求：见全校 Admission Requirements 页（TOEFL-iBT 80，2026-01-21 起为 4.5；IELTS 学术类总分 6.5 且各单项 5.5）。三、项目补充说明——具备以下资历者优先：数据科学或人工智能方向的优良荣誉学位；或相关学科的优良荣誉学位并有 2 年 IT 行业经验；或数据科学/AI 的优良学士学位并有 2 年 IT 行业经验。具备数据分析背景者亦可考虑。",
