    "descCn": "本研究生项目由香港浸会大学（HKBU）工商管理学院与北京师范大学-香港浸会大学联合国际学院（BNBU）工商管理学院联合开设。项目旨在培养符合社会需求的高层次会计专业人才与领导者，帮助有志于在会计与金融服务领域发展的学生拓展职业前景，既引导学生顺利进入理想职场，也为继续攻读更高学术层次者奠定扎实基础。课程涵盖财务会计、管理会计、审计等主要科目。",
