    "category": "金融",
    "desc": "The Master of Science in Data Science (Concentration in Quantitative Finance and Risk Management) programme is jointly offered by the Department of Mathematics, Hong Kong Baptist University (HKBU), and the Faculty of Science and Technology, Faculty of Business and Management, Beijing Normal-Hong Kong Baptist University (BNBU). It is developed based on the MSc in Mathematical Finance (MFIN) programme launched by HKBU in 2013. The principal aim of the programme is to equip students with advanced knowledge and skills in Data Science so that they can apply them to real-world problems in the financial industry. The curriculum places special emphasis on the integration of mathematics, data science, and finance, helping students not only master the application of cutting-edge technologies but also deeply understand the underlying mathematical principles. Graduates will possess the capability to identify problems in the financial and business sectors that can be solved by Data Science and to propose effective solutions.",
    "descEn": "The Master of Science in Data Science (Concentration in Quantitative Finance and Risk Management) programme is jointly offered by the Department of Mathematics, Hong Kong Baptist University (HKBU), and the Faculty of Science and Technology, Faculty of Business and Management, Beijing Normal-Hong Kong Baptist University (BNBU). It is developed based on the MSc in Mathematical Finance (MFIN) programme launched by HKBU in 2013. The principal aim of the programme is to equip students with advanced knowledge and skills in Data Science so that they can apply them to real-world problems in the financial industry. The curriculum places special emphasis on the integration of mathematics, data science, and finance, helping students not only master the application of cutting-edge technologies but also deeply understand the underlying mathematical principles. Graduates will possess the capability to identify problems in the financial and business sectors that can be solved by Data Science and to propose effective solutions.",
    "descCn": "数据科学理学硕士（量化金融与风险管理方向）由香港浸会大学数学系与北师港浸大理工学部、工商管理学院联合开设，其基础是浸大于 2013 年推出的金融数学理学硕士（MFIN）项目。项目主要目标是使学生掌握数据科学的高阶知识与技能，并能将其应用于金融业的真实问题。课程特别强调数学、数据科学与金融三者的融合，使学生不仅掌握前沿技术的应用，也深入理解其背后的数学原理。毕业生将具备识别金融与商业领域中可由数据科学解决的问题、并提出有效方案的能力。",
