    "nameCn": "数据科学理学硕士",
    "category": "数据科学",
    "desc": "此项目旨在培养能够满足市场对高级数据科学技能日益增长需求的数据分析人才，使毕业生能够运用数据科学技术，在组织决策中开展知识挖掘与成果输出。此外，本项目帮助数据分析从业者精进技术管理与研发能力；同时，为来自相关定量学科的学生铺就一条通往数据科学领域的畅通之路，助其快速完成向数据科学领域的职业转型。",
    "descCn": "此项目旨在培养能够满足市场对高级数据科学技能日益增长需求的数据分析人才，使毕业生能够运用数据科学技术，在组织决策中开展知识挖掘与成果输出。此外，本项目帮助数据分析从业者精进技术管理与研发能力；同时，为来自相关定量学科的学生铺就一条通往数据科学领域的畅通之路，助其快速完成向数据科学领域的职业转型。",
    "descEn": "The programme aims to produce data-analytic graduates to meet the growing demand for high-level data science skills and to prepare graduates to apply data science techniques to knowledge discovery and dissemination in organisational decision-making. It is also intended to help data analytic professionals upgrade their technical management and development skills, and to provide a solid path for students from related quantitative fields to rapidly transition to data science careers.\nProgram Intended Learning Outcomes:\nUpon successful completion of this Programme, students should be able to:\n· Apply knowledge of science and engineering appropriate to the data science discipline\n· Understand theoretical foundation of contemporary techniques and apply them for managing, mining and analyzing data across multiple disciplines\n· Comprehend computational tools and use data-driven thinking to discover new knowledge and to solve real-world problems with complex structures\n· Recognize the need for and engage in continuous learning about emerging and innovative data science techniques and ideas\n· Communicate ideas and findings in written, oral and visual forms and work in a diverse team environment",
    "requirements": "入学要求（官网「入学条件」栏原文，已在本项目页逐字核实；本校 7 个口径内项目页此栏第 1、2 项内容完全一致）：\n1. 基本入学要求\n毕业于认可的大学获得学士学位或等同大学本科的资历学位。\n2. 英语能力要求\n申请者如毕业于非英语授课的大学，必须符合以下的最低英语能力要求：\n· 大学英语六级：425分/合格；\n· 或托福：550(笔试)/79(机考)；对于托福成绩，申请者需要安排ETS将成绩报告直接发送至香港城市大学（东莞）。香港城市大学（东莞）的托福机构代码是D693。\n· 或雅思(学术)总分：6.0；\n· 或其他同等英语测试证明。\n* 仅指单次尝试的分数，不接受在家测试选项\n第一语言是英语，或从以英语为教学语言的机构获得了学士学位（或同等学历），无需提供英语成绩。\n@TOEFL 及 IELTS成绩有效期为2年。申请人需提交英语测试成绩，该获取成绩以大学开始报名日期前起计算2年内方为有效。\n各个专业可能规定更高的英语水平要求，或接受其他同等资格，视其学科特点而定。\n3. 学制学费\n学费 数据科学：145,000元/生/学年；学制 学制2年，最长学制3年；学习方式 全日制；申请费 免费；住宿费 双人间：1,200元/生/学年（10个月）、单人间：3,000元/生/学年（10个月）。\n* 说明：以上收费标准，适用于中国学生和国际学生。\n学生收到录取通知后，需在四周内支付第一笔学费人民币 30,000 元/生，以确认入学意向，此费用将在第一学年学费中抵减。\n本项目页「入学条件」栏未列出任何项目专属附加要求（已逐字核对全栏正文）。",
    "requirementsCn": "入学要求（官网「入学条件」栏原文，已在本项目页逐字核实；本校 7 个口径内项目页此栏第 1、2 项内容完全一致）：\n1. 基本入学要求\n毕业于认可的大学获得学士学位或等同大学本科的资历学位。\n2. 英语能力要求\n申请者如毕业于非英语授课的大学，必须符合以下的最低英语能力要求：\n· 大学英语六级：425分/合格；\n· 或托福：550(笔试)/79(机考)；对于托福成绩，申请者需要安排ETS将成绩报告直接发送至香港城市大学（东莞）。香港城市大学（东莞）的托福机构代码是D693。\n· 或雅思(学术)总分：6.0；\n· 或其他同等英语测试证明。\n* 仅指单次尝试的分数，不接受在家测试选项\n第一语言是英语，或从以英语为教学语言的机构获得了学士学位（或同等学历），无需提供英语成绩。\n@TOEFL 及 IELTS成绩有效期为2年。申请人需提交英语测试成绩，该获取成绩以大学开始报名日期前起计算2年内方为有效。\n各个专业可能规定更高的英语水平要求，或接受其他同等资格，视其学科特点而定。\n3. 学制学费\n学费 数据科学：145,000元/生/学年；学制 学制2年，最长学制3年；学习方式 全日制；申请费 免费；住宿费 双人间：1,200元/生/学年（10个月）、单人间：3,000元/生/学年（10个月）。\n* 说明：以上收费标准，适用于中国学生和国际学生。\n学生收到录取通知后，需在四周内支付第一笔学费人民币 30,000 元/生，以确认入学意向，此费用将在第一学年学费中抵减。\n本项目页「入学条件」栏未列出任何项目专属附加要求（已逐字核对全栏正文）。",
    "requirementsEn": "Entrance Requirement (official original text, verified verbatim on this programme page; sections 1 and 2 are identical across all seven in-scope programme pages of this institution):\n1. General Entrance Requirements\nApplicants must hold a bachelor's degree or an equivalent undergraduate qualification from a recognized university.\n2. English Proficiency Requirements\nApplicants who have graduated from a non-English medium university must meet the following minimum English proficiency standards:\n· CET-6: Score of 425 or Pass;\n· OR TOEFL: 550 (PBT) / 79 (iBT). For TOEFL scores, applicants should arrange for ETS to send the score report directly to City University of Hong Kong (Dongguan). The TOEFL institution code for City University of Hong Kong (Dongguan) is D693.\n· OR IELTS (Academic): Overall Band Score of 6.0;\n· OR other equivalent English test results.\n* Only scores from single test attempts are accepted, and home-based tests are not eligible. Applicants whose first language is English or who have obtained a bachelor's degree (or equivalent qualification) from an institution where the medium of instruction is English are exempt from providing an English test score.\nNote:\n· TOEFL and IELTS scores are valid for two years.\n· Programs may set higher English proficiency requirements or accept alternative qualifications, depending on their specific academic requirements.\n3. Academic Duration and Tuition Fees\nTuition Fees: MSc in Data Science: RMB 145,000 per student per academic year. Duration of Study: 2 years, maximum study period is 3 years. Mode of Study: Full-time. Application Fee: Free. Accommodation Fees: Double Room: 1,200 RMB per student per academic year (10 months); Single Room: 3,000 RMB per student per academic year (10 months). Additional Information: 1. The above fee structure applies to both Chinese and international students.\n2. After receiving the admission offer, students are required to pay an initial tuition deposit of RMB 30,000 within four weeks to confirm their acceptance. This deposit will be credited toward the first academic year's tuition.\nThis programme page lists no programme-specific additional entrance requirement.",
