    "applyWindow": "官网项目页「申请时间轴」栏原文：开放申请 截止至2026年7月31日；发放录取通知书 滚动录取；新生报到时间 2026年8月23-24日；迎新时间 2026年8月25-28日；开课时间 2026年8月31日。（英文页同栏原文：Application opens: Until July 31st, 2026. Admission offers issued: Rolling Basis. Enrollment Period: From August 23rd to August 24th, 2026. Orientation Period: From August 25th to August 28th, 2026. Program commencement: August 31st, 2026.）重要说明：该时间轴对应 2026 年入学（报到与开课均在 2026 年 8 月），截至 2026-09-21 该轮申请已截止；官网尚未公布 2027 年入学的申请轮次与截止日期，故本条 27 Fall 状态记为「待开放」，须待官网更新后重核。申请经研究生招生网「点击申请」入口（https://apply.cityu-dg.edu.cn/pg/a/login）提交，申请费官网明确为免费；招生活动见 https://pga.cityu-dg.edu.cn/admission-event ，常见问题见 /faq 。",
    "jointPartner": null,
    "location": "东莞（松山湖）",
    "website": "https://pga.cityu-dg.edu.cn/Business-and-Data-Analytics",
    "sourceConfidence": "official-listed",
    "sourceNote": "2026-09-20 首次浏览器实抓 pga.cityu-dg.edu.cn（港城大东莞研究生招生网，JS 渲染，静态抓取正文为空）项目页核实；2026-09-21 补抓中文项目页与 /en 英文项目页，回填英文简介原文、英文入学要求原文与官网申请时间轴。学费、学制、学习方式、申请费、住宿费、入学要求与英语要求均为官网原文照录（中文取自中文页，英文取自 /en 页）。本校 11 个研究生项目中，口径内 7 个（商务资讯系统、数据科学、创新创业、商业及数据分析、工程管理学、人工智能、计算机科学）已全部收录，且官网「学习方式」栏均为「全日制」；电机与电子工程学、生物医学工程、材料工程及纳米科技 3 个不在「商学院及商科交叉（数据分析/数据科学/人工智能/统计学/经济学）」口径内，故不收。计算机科学于 2026-09-21 按用户指示纳入：本项目官网课程目标明确含「拓宽学生在如人工智能、数据科学、信息安全、多媒体以及其他相关当代技术的知识面」，属商科交叉口径；且港五现有库中已收录 HKU 与 CityU 的计算机科学理学硕士，口径由此统一。官网未列开办年份，foundedYear 留空不推算。"
