    "tuitionNote": "官网原文「学制学费」栏：学费 计算机科学：人民币140,000元/生/学年；学制 学制2年，最长学制3年；学习方式 全日制；申请费 免费；住宿费 双人间：1,200元/生/学年（10个月）、单人间：3,000元/生/学年（10个月）。官网「说明」原文：以上收费标准，适用于中国学生和国际学生；学生收到录取通知后，需在四周内支付第一笔学费人民币 30,000 元/生，以确认入学意向，此费用将在第一学年学费中抵减。英文页同栏原文：MSc in Computer Science: RMB 140,000 per student per academic year; Mode of Study: Full-time; Application Fee: Free. 注意：官网学费以「每学年」计且未列全程总额，本库另按官网学制 2 年估算总额并已标注为估算。 估算总额 = 官网学年单价 × 官网学制 2 年 = 人民币 280,000 元；若按最长学制 3 年修读则更高，官网未列总额。",
